module tb_TopModule;
    reg [2:0] in;
    wire [1:0] out;

    TopModule u_dut (
        .in(in),
        .out(out)
    );

    initial begin
        integer i;
        reg [1:0] expected;
        integer errors;
        errors = 0;

        for (i = 0; i < 8; i = i + 1) begin
            in = i[2:0];
            #10;
            // Count ones
            expected = (i[0] ? 1 : 0) + (i[1] ? 1 : 0) + (i[2] ? 1 : 0);
            if (out !== expected) begin
                $display("FAIL: in=%b, expected=%0d, got=%0d", in, expected, out);
                errors = errors + 1;
            end
        end

        if (errors == 0) begin
            $display("SELFTEST PASS");
        end else begin
            $display("SELFTEST FAIL: %0d errors", errors);
        end
        $finish;
    end
endmodule
